components.css:
.ds-btn-console {
  font-family: 'Rajdhani', sans-serif; font-weight: 700; font-size: 21px; letter-spacing: 1px;
  color: #FFFFFF; padding: 10px 22px; cursor: pointer; user-select: none;
  border: 1px solid rgba(53, 224, 200, .40);
  background:
    linear-gradient(rgba(9, 12, 14, .58), rgba(9, 12, 14, .58)),
    linear-gradient(180deg, #2FC0AC 0%, #2FC0AC 3%, #8AEADC 8%, #8AEADC 44%, #35E0C8 52%, #35E0C8 92%, #8AEADC 96%, #2FC0AC 100%);
  box-shadow: 0 0 8px rgba(53, 224, 200, .30), inset 0 1px 0 rgba(53, 224, 200, .45), inset 0 -10px 14px rgba(0, 0, 0, .38);
  clip-path: polygon(8px 0, calc(100% - 8px) 0, 100% 8px, 100% calc(100% - 8px), calc(100% - 8px) 100%, 8px 100%, 0 calc(100% - 8px), 0 8px);
  transition: box-shadow .15s ease, transform .12s ease;
}
.ds-btn-console:hover { box-shadow: 0 0 16px rgba(53, 224, 200, .65), inset 0 1px 0 rgba(53, 224, 200, .60), inset 0 -10px 14px rgba(0, 0, 0, .38); }
.ds-btn-console:focus-visible { outline: 2px solid #35E0C8; outline-offset: 3px; }
.ds-btn-console:active { transform: translateY(2px); }

.ds-cta-forge {
  position: relative; display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: center;
  gap: 13px; width: 100%; min-height: 76px; padding: 12px 16px; text-align: left;
  color: #071012; cursor: pointer; overflow: hidden; border: 1px solid #FFE49A; border-radius: 0;
  clip-path: polygon(16px 0, 100% 0, 100% calc(100% - 16px), calc(100% - 16px) 100%, 0 100%, 0 16px);
  background: linear-gradient(135deg, rgba(255,255,255,.16), transparent 44%), linear-gradient(180deg, #FFE06B, #B98A1F);
  box-shadow: 0 12px 30px rgba(255, 210, 74, .18), 0 0 0 1px rgba(0, 0, 0, .35);
  transition: transform .18s ease, box-shadow .18s ease, filter .18s ease;
}
.ds-cta-forge::before { content: ''; position: absolute; inset: 0; background: linear-gradient(100deg, transparent 30%, rgba(255,255,255,.34) 50%, transparent 70%); transform: translateX(-130%); transition: transform .55s cubic-bezier(.2,.8,.2,1); pointer-events: none; }
.ds-cta-forge:hover { transform: translateY(-2px); filter: brightness(1.04); box-shadow: 0 16px 36px rgba(255, 210, 74, .24), 0 0 0 1px rgba(0, 0, 0, .35); }
.ds-cta-forge:hover::before { transform: translateX(130%); }
.ds-cta-forge:active { transform: translateY(0); }
.ds-cta-icon { display: grid; place-items: center; width: 46px; height: 46px; border-radius: 50%; border: 1px solid rgba(0,0,0,.25); background: rgba(0,0,0,.16); font-size: 18px; }
.ds-cta-copy { display: flex; flex-direction: column; gap: 2px; min-width: 0; }
.ds-cta-copy b { font-family: 'Orbitron', sans-serif; font-size: 30px; font-weight: 700; line-height: 1; letter-spacing: .1em; }
.ds-cta-copy small { font-family: ui-monospace, 'Cascadia Mono', Consolas, monospace; font-size: 15px; letter-spacing: .08em; text-transform: uppercase; opacity: .8; }
.ds-cta-chevron { font-family: 'Orbitron', sans-serif; font-size: 28px; line-height: 1; opacity: .5; }

.ds-tile-command {
  display: flex; align-items: center; gap: 9px; min-width: 0; min-height: 64px; padding: 9px 10px;
  color: #FFFFFF; text-align: left; cursor: pointer; border: 1px solid rgba(53,224,200,.20); border-left: 2px solid rgba(53,224,200,.55);
  border-radius: 0; clip-path: polygon(0 0, calc(100% - 9px) 0, 100% 9px, 100% 100%, 9px 100%, 0 calc(100% - 9px));
  background: linear-gradient(180deg, rgba(18,28,32,.88), rgba(8,12,16,.94));
  transition: transform .15s ease, border-color .15s ease, background .15s ease;
}
.ds-tile-command:hover { transform: translateY(-1px); border-color: rgba(53,224,200,.55); background: linear-gradient(180deg, rgba(24,38,42,.94), rgba(10,16,20,.98)); }
.ds-tile-icon { flex: 0 0 auto; display: grid; place-items: center; width: 30px; height: 30px; color: #35E0C8; border: 1px solid rgba(53,224,200,.28); background: rgba(53,224,200,.07); }
.ds-tile-copy { display: flex; flex: 1 1 auto; flex-direction: column; gap: 2px; min-width: 0; }
.ds-tile-copy b { font-family: 'Rajdhani', sans-serif; font-size: 18px; font-weight: 700; letter-spacing: .04em; line-height: 1.05; }
.ds-tile-copy small { font-family: ui-monospace, 'Cascadia Mono', Consolas, monospace; font-size: 15px; line-height: 1.2; opacity: .72; }

.ds-card-upgrade {
  display: flex; flex-direction: column; gap: 8px; width: 170px; min-height: 210px; padding: 12px 10px;
  color: #E8FFF6; text-align: center; cursor: pointer; font-family: 'Rajdhani', sans-serif;
  border: 1.5px solid #7FE0C8; border-radius: 12px;
  background: linear-gradient(180deg, #2A4D44, #16332C);
  box-shadow: 0 0 16px rgba(53,224,200,.22), inset 0 0 12px rgba(15,42,40,.5);
  transition: box-shadow .18s ease, border-color .18s ease, transform .12s ease;
}
.ds-card-upgrade:hover { border-color: #B7FFE9; box-shadow: 0 0 26px rgba(53,224,200,.65), 0 0 46px rgba(53,224,200,.30), inset 0 0 16px rgba(53,224,200,.25); }
.ds-card-upgrade:active { transform: translateY(2px) scale(.98); }
.ds-card-unit { align-self: center; max-width: 100%; padding: 1px 8px; border: 1px solid rgba(53,224,200,.45); border-radius: 999px; font-family: ui-monospace, 'Cascadia Mono', Consolas, monospace; font-size: 15px; color: #35E0C8; white-space: nowrap; }
.ds-card-title { font-family: 'Orbitron', sans-serif; font-size: 21px; font-weight: 700; line-height: 1.2; }
.ds-card-desc { font-size: 16px; line-height: 1.35; color: rgba(232,255,246,.82); }
.ds-card-rarity { margin-top: auto; font-family: ui-monospace, 'Cascadia Mono', Consolas, monospace; font-size: 15px; letter-spacing: .1em; color: #35E0C8; }

.ds-chip-data {
  display: inline-flex; align-items: center; gap: 6px; padding: 4px 10px;
  border: 1px solid rgba(53,224,200,.35); border-radius: 999px; background: rgba(15,42,40,.85);
  color: #35E0C8; font-family: ui-monospace, 'Cascadia Mono', Consolas, monospace; font-size: 15px; letter-spacing: .5px;
  white-space: nowrap;
}

.ds-panel-screen {
  display: flex; flex-direction: column; align-items: center; gap: 12px; width: 320px; padding: 22px 20px;
  color: #FFFFFF; text-align: center; font-family: 'Rajdhani', sans-serif;
  border: 1px solid rgba(53,224,200,.28); border-radius: 12px;
  background: linear-gradient(180deg, rgba(18,24,28,.94), rgba(10,13,16,.96));
  box-shadow: 0 0 22px rgba(53,224,200,.14), inset 0 0 18px rgba(15,42,40,.30);
}
.ds-panel-screen h3 { font-family: 'Orbitron', sans-serif; font-size: 28px; letter-spacing: 3px; margin: 0; }
.ds-panel-screen p { font-size: 16px; color: #9FB4C8; margin: 0; }

.ds-hud-readout {
  display: inline-flex; align-items: center; gap: 7px; min-height: 48px; padding: 6px 11px;
  border: 1px solid rgba(159,180,200,.16); border-left-color: #35E0C8; border-right-color: #35E0C8;
  background: rgba(15,42,40,.85); font-family: 'Rajdhani', sans-serif;
}
.ds-hud-label { font-family: ui-monospace, 'Cascadia Mono', Consolas, monospace; font-size: 15px; letter-spacing: 1px; color: #9FB4C8; text-transform: uppercase; }
.ds-hud-value { font-family: 'Exo2', ui-monospace, monospace; font-size: 21px; color: #FFFFFF; }
